def roman_to_int(s):
    """Convert an uppercase Roman numeral string to its integer value.
    Must handle subtractive forms (IV=4, IX=9, XL=40, XC=90, CD=400, CM=900)."""
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    prev = 0
    for ch in reversed(s):
        curr = roman[ch]
        if curr < prev:
            result -= curr
        else:
            result += curr
        prev = curr
    return result
